48	namespace prim = ::sg::sm90::primitives;
49	using ::sg::algorithms::sg11_phi_forward;
50	using ::sg::algorithms::sg11_sweep_a_step;
51	using ::sg::algorithms::sg11_sweep_b_step;
52	using ::sg::algorithms::sg11_adam_tail;
53	
54	constexpr int SG11_H = 64;
55	
56	// Minimum resident blocks/SM for the element-wise sweeps. Caps registers so
57	// occupancy stays high on the (memory-bound) Adam apply.
58	#ifndef SG_SUPERGROK11_MIN_BLOCKS
59	#define SG_SUPERGROK11_MIN_BLOCKS 4
60	#endif
61	
62	// Cooperatively stage the per-element meta-net phi weights into shared memory
63	// ONCE per block, then hand the shared pointers to the canonical
64	// sg11_phi_forward<H>. W1 is [H,2] (row-major, 2 inputs/hidden unit), b1/W2 are
65	// [H]. The same weights are read by every element this block processes; staging
66	// removes the per-element re-read from GLOBAL inside the H-wide forward loop. NO
67	// math/signature change — the fn still takes const float* (single-sourced in
68	// algorithms/supergrok11.h).
69	template <int H>
70	__device__ __forceinline__ void sg11_stage_phi_weights(
71	    const float* __restrict__ W1, const float* __restrict__ b1,
72	    const float* __restrict__ W2,
73	    float* sW1, float* sb1, float* sW2
74	) {
75	    for (int j = threadIdx.x; j < H * 2; j += blockDim.x) sW1[j] = W1[j];
76	    for (int j = threadIdx.x; j < H;     j += blockDim.x) { sb1[j] = b1[j]; sW2[j] = W2[j]; }
77	    __syncthreads();
78	}
