80	template <typename GradT>
81	__global__ void __launch_bounds__(SG_TUNED_BLOCK_SIZE, SG_SUPERGROK11_MIN_BLOCKS)
82	sg11_sweep_a_kernel(
83	    float* mu_out, const GradT* grad, const float* sharpness, const float* momentum,
84	    const float* W1, const float* b1, const float* W2, float b2,
85	    float* gate_num_p, float* gate_den_g_p, float* gate_den_m_p,
86	    int64_t N
87	) {
88	    __shared__ float sW1[SG11_H * 2];
89	    __shared__ float sb1[SG11_H];
90	    __shared__ float sW2[SG11_H];
91	    sg11_stage_phi_weights<SG11_H>(W1, b1, W2, sW1, sb1, sW2);
92	
93	    float gn = 0.0f, gdg = 0.0f, gdm = 0.0f;
94	    const int64_t stride = prim::grid_stride();
95	    for (int64_t i = prim::grid_stride_index(); i < N; i += stride) {
96	        SG_SANITIZE_GRAD_INPLACE(grad, i);
97	        const float g = static_cast<float>(grad[i]);
98	        const float s = sharpness[i];
99	        const float mu_val = sg11_phi_forward<SG11_H>(g, s, sW1, sb1, sW2, b2);
100	        sg11_sweep_a_step(mu_out, grad, sharpness, momentum, mu_val, i,
101	                          gn, gdg, gdm);
102	    }
103	    float r1 = prim::block_reduce_sum_f32(gn);
104	    float r2 = prim::block_reduce_sum_f32(gdg);
105	    float r3 = prim::block_reduce_sum_f32(gdm);
106	    if (threadIdx.x == 0) {
107	        atomicAdd(gate_num_p, r1);
108	        atomicAdd(gate_den_g_p, r2);
109	        atomicAdd(gate_den_m_p, r3);
110	    }
111	}
