113	template <typename ParamT, typename GradT, int UNROLL>
114	__global__ void __launch_bounds__(SG_TUNED_BLOCK_SIZE, SG_SUPERGROK11_MIN_BLOCKS)
115	sg11_sweep_b_kernel(
116	    ParamT* param, float* exp_avg, float* exp_avg_sq,
117	    const GradT* grad, const float* mu, float gate,
118	    float alpha, float lr, float beta1, float beta2, float eps, float wd,
119	    float bc1, float bc2, int64_t N
120	) {
121	    const int64_t stride = prim::grid_stride() * UNROLL;
122	    const int64_t base0 = prim::grid_stride_index() * UNROLL;
123	    for (int64_t base = base0; base < N; base += stride) {
124	        #pragma unroll
125	        for (int u = 0; u < UNROLL; ++u) {
126	            const int64_t i = base + u;
127	            if (i < N) {
128	                SG_SANITIZE_GRAD_INPLACE(grad, i);
129	                sg11_sweep_b_step(param, exp_avg, exp_avg_sq, grad, mu, gate,
130	                                  alpha, lr, beta1, beta2, eps, wd, bc1, bc2, i);
131	            }
132	        }
133	    }
134	}
