136	// FP32 vec4 sweep B: float4 traffic on param/state/grad/mu, canonical
137	// sg11_sweep_b_step CALLED 4× on the register lanes. Math is NOT re-typed here.
138	__global__ void __launch_bounds__(SG_TUNED_BLOCK_SIZE, SG_SUPERGROK11_MIN_BLOCKS)
139	sg11_sweep_b_kernel_vec4_fp32(
140	    float4* param4, float4* exp_avg4, float4* exp_avg_sq4,
141	    const float4* grad4, const float4* mu4, float gate,
142	    float alpha, float lr, float beta1, float beta2, float eps, float wd,
143	    float bc1, float bc2, int64_t N4
144	) {
145	    const int64_t stride = prim::grid_stride();
146	    for (int64_t i = prim::grid_stride_index(); i < N4; i += stride) {
147	        float4 p  = prim::ld_f32v4(param4 + i);
148	        float4 m  = prim::ld_f32v4(exp_avg4 + i);
149	        float4 v  = prim::ld_f32v4(exp_avg_sq4 + i);
150	        float4 g  = prim::ldg_f32v4(grad4 + i);
151	        float4 mu = prim::ldg_f32v4(mu4 + i);
152	        ::grokking::sm90::sg_sanitize_grad4(g);
153	        #pragma unroll
154	        for (int u = 0; u < 4; ++u) {
155	            sg11_sweep_b_step(&p.x, &m.x, &v.x, &g.x, &mu.x, gate,
156	                              alpha, lr, beta1, beta2, eps, wd, bc1, bc2, u);
157	        }
158	        prim::st_f32v4(param4 + i, p);
159	        prim::st_f32v4(exp_avg4 + i, m);
160	        prim::st_f32v4(exp_avg_sq4 + i, v);
161	    }
162	}
