164	void launch_supergrok11_step(
165	    torch::Tensor& param,
166	    torch::Tensor& exp_avg,
167	    torch::Tensor& exp_avg_sq,
168	    torch::Tensor& mu_buf,
169	    const torch::Tensor& grad,
170	    const torch::Tensor& sharpness,
171	    const torch::Tensor& momentum,
172	    const torch::Tensor& phi_W1,
173	    const torch::Tensor& phi_b1,
174	    const torch::Tensor& phi_W2,
175	    float phi_b2,
176	    torch::Tensor& gate_partials,  // [3] {num, den_g, den_m}
177	    float alpha,
178	    float lr, float beta1, float beta2, float eps, float wd,
179	    float bc1, float bc2
180	) {
181	    const int64_t N = param.numel();
182	    if (N == 0) return;
183	
184	    auto stream = at::cuda::getCurrentCUDAStream().stream();
185	
186	    // §6.1: keep the Adam moments (m, v) L2-resident across the step.
187	    prim::L2PersistScope l2(stream,
188	        exp_avg.data_ptr(), exp_avg.nbytes(),
189	        exp_avg_sq.data_ptr(), exp_avg_sq.nbytes());
190	
191	    const int block = SG_TUNED_BLOCK_SIZE;
192	    const int grid = static_cast<int>(
193	        std::min<int64_t>(65535, (N + block - 1) / block));
194	
195	    gate_partials.zero_();
196	
197	    AT_DISPATCH_FLOATING_TYPES_AND2(
198	        at::ScalarType::Half, at::ScalarType::BFloat16,
199	        grad.scalar_type(), "sg11_sweep_a", [&] {
200	            sg11_sweep_a_kernel<scalar_t><<<grid, block, 0, stream>>>(
201	                mu_buf.data_ptr<float>(),
202	                grad.data_ptr<scalar_t>(),
203	                sharpness.data_ptr<float>(),
204	                momentum.data_ptr<float>(),
205	                phi_W1.data_ptr<float>(),
206	                phi_b1.data_ptr<float>(),
207	                phi_W2.data_ptr<float>(),
208	                phi_b2,
209	                gate_partials.data_ptr<float>(),
210	                gate_partials.data_ptr<float>() + 1,
211	                gate_partials.data_ptr<float>() + 2,
212	                N);
213	            SG_LAUNCH_CHECK(stream);
214	        });
215	
216	    // Host-side reduction of the 3 scalars and gate clamp.
217	    auto partials_cpu = gate_partials.to(torch::kCPU);
218	    float gn  = partials_cpu[0].item<float>();
219	    float gdg = partials_cpu[1].item<float>();
220	    float gdm = partials_cpu[2].item<float>();
221	    float denom = sqrtf(gdg * gdm + 1e-12f);
222	    float gate = (denom > 0.0f) ? (gn / denom) : 0.0f;
223	    gate = fminf(fmaxf(gate, 0.0f), 1.0f);
224	
225	    const bool all_fp32 = param.scalar_type() == torch::kFloat32 &&
226	                          grad.scalar_type() == torch::kFloat32;
227	    if (SG_TUNED_VEC_WIDTH == 4 && all_fp32 &&
228	        prim::is_vec4_alignable(param.data_ptr(), N) &&
229	        prim::is_vec4_alignable(exp_avg.data_ptr(), N) &&
230	        prim::is_vec4_alignable(exp_avg_sq.data_ptr(), N) &&
231	        prim::is_vec4_alignable(grad.data_ptr(), N) &&
232	        prim::is_vec4_alignable(mu_buf.data_ptr(), N)) {
233	        const int64_t N4 = N / 4;
234	        const int grid4 = static_cast<int>(
235	            std::min<int64_t>(65535, (N4 + block - 1) / block));
236	        sg11_sweep_b_kernel_vec4_fp32<<<grid4, block, 0, stream>>>(
237	            reinterpret_cast<float4*>(param.data_ptr<float>()),
238	            reinterpret_cast<float4*>(exp_avg.data_ptr<float>()),
239	            reinterpret_cast<float4*>(exp_avg_sq.data_ptr<float>()),
240	            reinterpret_cast<const float4*>(grad.data_ptr<float>()),
241	            reinterpret_cast<const float4*>(mu_buf.data_ptr<float>()),
242	            gate, alpha, lr, beta1, beta2, eps, wd, bc1, bc2, N4);
243	        SG_LAUNCH_CHECK(stream);
244	        return;
245	    }
246	
247	    AT_DISPATCH_FLOATING_TYPES_AND2(
248	        at::ScalarType::Half, at::ScalarType::BFloat16,
249	        param.scalar_type(), "sg11_sweep_b", [&] {
250	            sg11_sweep_b_kernel<scalar_t, scalar_t, SG_TUNED_UNROLL>
251	                <<<grid, block, 0, stream>>>(
252	                param.data_ptr<scalar_t>(),
253	                exp_avg.data_ptr<float>(),
254	                exp_avg_sq.data_ptr<float>(),
255	                grad.data_ptr<scalar_t>(),
256	                mu_buf.data_ptr<float>(),
257	                gate, alpha, lr, beta1, beta2, eps, wd, bc1, bc2, N);
258	            SG_LAUNCH_CHECK(stream);
259	        });
260	}
