263	// Meta-net forward: mu[i] = phi(grad[i], sharpness[i]); smart_grad = grad + alpha*mu
264	template <typename GradT>
265	__global__ void __launch_bounds__(SG_TUNED_BLOCK_SIZE, SG_SUPERGROK11_MIN_BLOCKS)
266	sg11_mu_metanet_kernel(
267	    float* mu, const GradT* grad, const float* sharpness,
268	    float* smart_grad, float alpha,
269	    const float* W1, const float* b1, const float* W2, float b2_scalar,
270	    float rescale, int64_t N
271	) {
272	    __shared__ float sW1[SG11_H * 2];
273	    __shared__ float sb1[SG11_H];
274	    __shared__ float sW2[SG11_H];
275	    sg11_stage_phi_weights<SG11_H>(W1, b1, W2, sW1, sb1, sW2);
276	
277	    const int64_t stride = prim::grid_stride();
278	    for (int64_t i = prim::grid_stride_index(); i < N; i += stride) {
279	        SG_SANITIZE_GRAD_INPLACE(grad, i);
280	        float g = static_cast<float>(grad[i]);
281	        float s = sharpness[i];
282	        float phi = sg11_phi_forward<SG11_H>(g, s, sW1, sb1, sW2, b2_scalar) * rescale;
283	        mu[i] = phi;
284	        smart_grad[i] = g + alpha * phi;
285	    }
286	}
