289	    torch::Tensor mu, torch::Tensor grad, torch::Tensor sharpness,
290	    torch::Tensor smart_grad, float alpha,
291	    torch::Tensor W1, torch::Tensor b1, torch::Tensor W2, torch::Tensor b2,
292	    float rescale, int hidden_dim
293	) {
294	    const int64_t N = mu.numel();
295	    if (N == 0) return;
296	    auto stream = at::cuda::getCurrentCUDAStream().stream();
297	    const int block = SG_TUNED_BLOCK_SIZE;
298	    const int grid = static_cast<int>(
299	        std::min<int64_t>(65535, (N + block - 1) / block));
300	    float b2_val = b2.item<float>();
301	
302	    AT_DISPATCH_FLOATING_TYPES_AND2(
303	        at::ScalarType::Half, at::ScalarType::BFloat16,
304	        grad.scalar_type(), "sg11_mu_metanet", [&] {
