306	                mu.data_ptr<float>(),
307	                grad.data_ptr<scalar_t>(),
308	                sharpness.data_ptr<float>(),
309	                smart_grad.data_ptr<float>(), alpha,
310	                W1.data_ptr<float>(), b1.data_ptr<float>(),
311	                W2.data_ptr<float>(), b2_val, rescale, N);
312	            SG_LAUNCH_CHECK(stream);
313	        });
