426	// Cosine gate: cos_sim(smart_grad, mu) clamped to [0,1].
427	float compute_cosine_gate_fused(
428	    torch::Tensor smart_grad, torch::Tensor mu, float gate_temp
429	) {
430	    auto sg_f = smart_grad.to(torch::kFloat32).flatten();
431	    auto mu_f = mu.to(torch::kFloat32).flatten();
432	    float num = (sg_f * mu_f).sum().item<float>();
433	    float den_g = (sg_f * sg_f).sum().item<float>();
434	    float den_m = (mu_f * mu_f).sum().item<float>();
435	    float denom = sqrtf(den_g * den_m + 1e-12f);
436	    float gate = (denom > 0.0f) ? (num / denom) : 0.0f;
437	    return fminf(fmaxf(gate, 0.0f), 1.0f);
438	}
